(()=>{const path=location.pathname;const nested=/\/events\//.test(path);const prefix=nested?"../":"";const lang=()=>document.documentElement.lang==="en"?"en":"fr";const apiBase="https://twjpjzalyvbsdpbzhqln.supabase.co/functions/v1";const page=path.split("/").pop()||"index.html";const pageClass=(()=>{if(page==="index.html"||page==="")return"premium-page-home";if(page==="classement.html")return"premium-page-ranking";if(page==="reglement.html")return"premium-page-rules";if(page==="gtworld.html")return"premium-page-gtworld";if(page==="daily-race.html")return"premium-page-daily";if(page==="open-lobby.html")return"premium-page-open-lobby";if(page==="calendrier.html")return"premium-page-calendar";if(page==="archives.html")return"premium-page-archives";if(page==="profil-pilote.html")return"premium-page-profile";if(page==="course.html"||nested)return"premium-page-course";if(page==="event-admin.html")return"premium-page-admin";if(page==="confidentialite.html")return"premium-page-privacy";return"premium-page-generic"})();document.body.classList.add("premium-site",pageClass);const isActive=href=>{const[targetLocation,targetHash=""]=href.split("#");const targetPage=targetLocation.split("?")[0];const currentHash=location.hash.replace("#","")||"points";if(targetPage==="index.html")return page===""||page==="index.html";if(targetPage==="classement.html"&&targetHash)return page===targetPage&&currentHash===targetHash;return page===targetPage};const nav=document.querySelector(".side-links");if(nav){const groups=[{id:"courses",fr:"Courses",en:"Races",items:[["gtworld.html","WorldGT","WorldGT"],["daily-race.html","Daily Race","Daily Race"],["open-lobby.html","Open Lobby","Open Lobby"]]},{id:"calendar",fr:"Calendrier",en:"Calendar",items:[["calendrier.html?type=WGT","WorldGT","WorldGT"],["calendrier.html?type=DR","Daily Race","Daily Race"],["calendrier.html?type=OL","Open Lobby","Open Lobby"]]},{id:"ranking",fr:"Classements",en:"Standings",items:[["gtworld.html#classement-equipes","WorldGT","WorldGT"],["classement.html?type=DR#points","Daily Race","Daily Race"],["classement.html?type=OL#points","Open Lobby","Open Lobby"]]},{id:"laps",fr:"Meilleurs temps",en:"Best laps",items:[["classement.html#circuit","Par circuit","By circuit"],["classement.html#driver","Par pilote","By driver"]]}];const makeLink=([href,fr,en])=>{const a=document.createElement("a");a.href=prefix+href;a.dataset.fr=fr;a.dataset.en=en;a.textContent=lang()==="en"?en:fr;return a};const activeGroup=()=>page==="gtworld.html"&&location.hash==="#classement-equipes"?"ranking":page==="course.html"||nested?"courses":page==="calendrier.html"?"calendar":page==="classement.html"?["circuit","driver"].includes(location.hash.slice(1))?"laps":"ranking":["gtworld.html","daily-race.html","open-lobby.html"].includes(page)?"courses":"";const matchLink=href=>{const category=document.querySelector("[data-public-event]")?.dataset.eventCategory;if((page==="course.html"||nested)&&category)return href===({WGT:"gtworld.html",DR:"daily-race.html",OL:"open-lobby.html"}[category]);if(page==="gtworld.html"&&(href==="gtworld.html"||href==="gtworld.html#classement-equipes"))return href==="gtworld.html#classement-equipes"?(location.hash==="#classement-equipes"):location.hash!=="#classement-equipes";const u=new URL(href,location.href);if(u.pathname!==location.pathname)return false;if(page==="classement.html")return (u.hash||"#points")===(location.hash||"#points")&&(u.hash==="#circuit"||u.hash==="#driver"||u.searchParams.get("type")===(new URLSearchParams(location.search).get("type")||"DR"));if(page==="calendrier.html")return u.searchParams.get("type")===(new URLSearchParams(location.search).get("type")||"WGT");return true};const home=makeLink(["index.html","Accueil","Home"]);const footerLinks=[makeLink(["archives.html","Archives","Archives"]),makeLink(["reglement.html","Règlement","Rules"])];const groupNodes=groups.map(g=>{const wrap=document.createElement("div");wrap.className="side-nav-group side-nav-section";wrap.dataset.group=g.id;const button=document.createElement("button");button.type="button";button.className="side-nav-group-toggle";button.dataset.fr=g.fr;button.dataset.en=g.en;button.textContent=lang()==="en"?g.en:g.fr;button.setAttribute("aria-expanded","false");button.setAttribute("aria-label",g.fr);const panel=document.createElement("div");panel.className="side-submenu";panel.id="atx-nav-"+g.id;button.setAttribute("aria-controls",panel.id);g.items.forEach(item=>panel.append(makeLink(item)));wrap.append(button,panel);button.addEventListener("click",()=>{const open=!wrap.classList.contains("open");groupNodes.forEach(n=>setOpen(n,false));setOpen(wrap,open)});return wrap});const setOpen=(node,open)=>{node.classList.toggle("open",open);node.querySelector("button").setAttribute("aria-expanded",String(open));node.querySelector(".side-submenu").hidden=!open};nav.replaceChildren(home,...groupNodes,...footerLinks);const sync=()=>{const active=activeGroup();groupNodes.forEach(node=>{const selected=node.dataset.group===active;node.querySelector("button").classList.toggle("active",selected);node.querySelectorAll("a").forEach(link=>{const yes=matchLink(link.getAttribute("href"));link.classList.toggle("active",yes);if(yes)link.setAttribute("aria-current","page");else link.removeAttribute("aria-current")})});nav.querySelectorAll(":scope>a").forEach(link=>link.classList.toggle("active",page===(link.getAttribute("href")||"").split("#")[0]));if(!groupNodes.some(node=>node.classList.contains("open")))groupNodes.forEach(node=>setOpen(node,node.dataset.group===active))};groupNodes.forEach(node=>setOpen(node,node.dataset.group===activeGroup()));sync();window.addEventListener("hashchange",()=>{groupNodes.forEach(node=>setOpen(node,node.dataset.group===activeGroup()));sync()});document.addEventListener("atx:eventcategory",()=>{groupNodes.forEach(node=>setOpen(node,node.dataset.group===activeGroup()));sync()});document.addEventListener("atx:rankingcategory",sync);document.addEventListener("keydown",e=>{if(e.key==="Escape"&&nav.contains(document.activeElement)){groupNodes.forEach(node=>setOpen(node,false));document.activeElement.blur()}})}
const footer=document.querySelector(".site-footer");if(footer){footer.innerHTML=`<div class="wrap"><div class="premium-footer-grid"><div><a class="brand" href="${prefix}index.html">ATX <span>Racing</span></a><p class="premium-footer-copy" data-fr="Compétition ACC, événements, classements et progression pilote — une identité ATX Motorsport." data-en="ACC competition, events, standings and driver progression — an ATX Motorsport identity.">Compétition ACC, événements, classements et progression pilote — une identité ATX Motorsport.</p></div><nav class="premium-footer-links" aria-label="Footer"><a href="${prefix}index.html">Accueil</a><a href="${prefix}gtworld.html">WorldGT</a><a href="${prefix}daily-race.html">Daily Race</a><a href="${prefix}open-lobby.html">Open Lobby</a><a href="${prefix}calendrier.html">Calendrier</a><a href="${prefix}classement.html">Classements</a><a href="${prefix}archives.html">Archives</a><a href="${prefix}reglement.html">Règlement</a><a href="https://www.thesimgrid.com/communities/atxracing" target="_blank" rel="noopener">SimGrid</a><a href="https://discord.gg/dgyJJYTSsD" target="_blank" rel="noopener">Discord</a><a href="${prefix}confidentialite.html">Confidentialité</a></nav></div><div class="premium-footer-legal"><span>© 2026 ATX Racing · ATX Motorsport</span><a href="mailto:athoxmotorsport@gmail.com">athoxmotorsport@gmail.com</a></div></div>`}const main=document.querySelector("main");let ticker=main?.querySelector(".live-ticker");if(main&&!ticker){ticker=document.createElement("div");ticker.className="live-ticker premium-global-ticker";ticker.setAttribute("aria-label","Informations ATX Racing");ticker.innerHTML='<div class="live-ticker-track" data-premium-ticker-track></div>';main.prepend(ticker)}const track=ticker?.querySelector(".live-ticker-track");const localDate=value=>new Intl.DateTimeFormat(lang()==="en"?"en-GB":"fr-BE",{dateStyle:"medium",timeStyle:"short",timeZone:"Europe/Brussels"}).format(new Date(value));const renderTicker=events=>{if(!track)return;const now=Date.now();const next=(events||[]).filter((e=>new Date(e.starts_at).getTime()>=now)).sort(((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)))[0];const messages=next?[lang()==="en"?`Next event · ${next.title||next.title_fr||next.circuit_name||"ATX Racing"}`:`Prochain événement · ${next.title||next.title_fr||next.circuit_name||"ATX Racing"}`,localDate(next.starts_at),lang()==="en"?"Registration via SimGrid":"Inscriptions via SimGrid",lang()==="en"?"Official results · Performance · SAFE":"Résultats officiels · Performance · SAFE","Assetto Corsa Competizione · GT3"]:[lang()==="en"?"ATX Racing · Next event in preparation":"ATX Racing · Prochain événement en préparation",lang()==="en"?"Calendar and registration via SimGrid":"Calendrier et inscriptions via SimGrid",lang()==="en"?"Official results · Performance · SAFE":"Résultats officiels · Performance · SAFE","Assetto Corsa Competizione · GT3"];const fragment=document.createDocumentFragment();for(let copy=0;copy<2;copy+=1){messages.forEach((message=>{const item=document.createElement("span");item.className="live-ticker-item";item.textContent=message;fragment.append(item)}))}track.replaceChildren(fragment)};if(track)fetch(`${apiBase}/public-event`,{cache:"no-store"}).then((r=>r.ok?r.json():Promise.reject())).then((p=>renderTicker(p.events||[]))).catch((()=>renderTicker([])));const circuitHeading=document.querySelector('[data-ranking-panel="circuit"] .ranking-panel-head h2');if(circuitHeading)circuitHeading.innerHTML='<span class="premium-red">CLASSEMENT</span><br>MEILLEURS TOURS <span class="premium-outline">PAR CIRCUIT</span>';const decorateSectionHeadings=()=>{document.querySelectorAll("main section .wrap").forEach((wrap=>{const label=wrap.querySelector(":scope > .section-label");const heading=wrap.querySelector(":scope > h1, :scope > h2");if(label&&heading)wrap.classList.add("premium-section-heading")}))};decorateSectionHeadings();const fixRedBullRingImage=()=>{document.querySelectorAll(".circuit-visual-card").forEach((card=>{const name=card.querySelector(".circuit-card-name")?.textContent?.trim().toLowerCase()||"";if(!name.includes("red bull ring"))return;const img=card.querySelector(".circuit-card-media img");if(!img)return;const replacement="https://gdm-universal-media.b-cdn.net/racinggames/77340ace8cf3f6e652f0d196344d7d7a304b9083-3840x2160.jpg?height=840&width=1600";if(img.src!==replacement)img.src=replacement;img.alt="Red Bull Ring dans Assetto Corsa Competizione"}))};fixRedBullRingImage();if(page==="classement.html"){const rankingRoot=document.querySelector("[data-alltime-leaderboard]")||document.body;new MutationObserver((()=>fixRedBullRingImage())).observe(rankingRoot,{childList:true,subtree:true})}document.addEventListener("click",(event=>{if(event.target.closest("[data-language],[data-lang-switch]"))setTimeout((()=>{document.querySelectorAll("[data-fr][data-en]").forEach((el=>{el.textContent=el.dataset[lang()]||el.textContent}));if(track)fetch(`${apiBase}/public-event`,{cache:"no-store"}).then((r=>r.ok?r.json():{})).then((p=>renderTicker(p.events||[]))).catch((()=>{}))}),0)}))})();